mapper.select:
select DISTINCT
CAST(ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{longitude},' ',#{latitude},')')), ST_GeomFromText(CONCAT('POINT(',d.longitude,' ',d.latitude,')')) ) as DECIMAL(65,2)) as distance,
d.id, d.resource_id, d.resource_name, d.resource_type_id, z.resource_type_name, d.order_num, d.`status`, d.delete_flag, d.creator, d.create_time, d.modifier, d.update_time, d.tenant_id, s.tenant_name, d.remark, d.longitude, d.latitude, d.elevation, d.addr, d.industry_code, d.app_ver_code, d.resource_property, st_astext(d.geometry) as geometry, d.color, a.area_name as province_name, b.area_name as city_name, z.icon, d.img_url, d.`admin`,
case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
d.tel from resource_conf d left join resource_type z on d.resource_type_id=z.resource_type_id and d.tenant_id = z.tenant_id and d.industry_code = z.industry_code left join sys_tenant_info s on d.tenant_id = s.tenant_id left join sys_area a on a.area_code=s.province_id left join sys_area b on b.area_code=s.city_id
LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = d.resource_id AND dct.coll_obj_type = '14' AND dct.user_id = #{userId}
where d.delete_flag = 0 and z.delete_flag = 0
${dataScope}
AND d.resource_name like CONCAT(CONCAT('%',#{resourceName}),'%')
AND z.resource_type_name like CONCAT(CONCAT('%',#{resourceTypeName}),'%')
AND z.type_level_url like CONCAT(CONCAT('%',#{typeLevelUrl}),'%')
AND d.longitude = #{longitudeParam}
AND d.latitude = #{latitudeParam}
AND d.elevation = #{elevation}
AND s.tenant_name like CONCAT(CONCAT('%',#{tenantName}),'%')
AND d.tenant_id = #{tenantId}
AND d.industry_code = #{industryCode}
AND d.app_ver_code = #{appVerCode}
AND d.resource_type_id = #{resourceTypeId}
AND d.resource_property = #{resourceProperty}
AND (d.LONGITUDE != '' or d.LONGITUDE != '' or d.LONGITUDE != null or d.LONGITUDE != null) and ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{longitude},' ',#{latitude},')')), ST_GeomFromText(CONCAT('POINT(',d.longitude,' ',d.latitude,')')) ) <= #{radius}
AND d.resource_type_id IN
#{item}
ORDER BY CONVERT(z.resource_type_name USING GBK)
desc
order by d.elevation + 0
desc
order by d.update_time desc,d.ID DESC

select
    count(1)
from
    resource_conf
where
    resource_name = #{resourceName}
    and delete_flag = 0

      and tenant_id = #{tenantId,jdbcType=VARCHAR}


      and resource_id != #{resourceId}


      and industry_code = #{industryCode}

SELECT d.RESOURCE_ID AS id, d.RESOURCE_NAME AS label, d.RESOURCE_TYPE_ID as pid, '1' as type, '' as icon, d.resource_property,
case when IFNULL(er.id,0) = 0 then '0' else '1' end isEmergency,
case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor FROM resource_conf d left join resource_type z on d.resource_type_id=z.resource_type_id and d.tenant_id = z.tenant_id and d.industry_code = z.industry_code LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = d.resource_id AND dct.coll_obj_type = '14' AND dct.user_id = #{userId}
LEFT JOIN vm_emergency_resource_info er ON d.RESOURCE_ID = er.resource_id AND d.TENANT_ID = er.tenant_id AND d.industry_code = er.industry_code AND d.app_ver_code = er.app_ver_code
AND er.event_code = #{eventCode}
AND er.stage_id = #{stageId}
AND er.task_id = #{taskId}
where d.DELETE_FLAG = 0 and z.delete_flag = 0 and d.status='0' and d.tenant_id = #{tenantId,jdbcType=VARCHAR} and d.industry_code = #{industryCode,jdbcType=VARCHAR}
AND d.app_ver_code = #{appVerCode}
AND d.resource_property = #{resourceProperty}
and dct.user_device_coll_id IS NOT NULL
${dataScope}
union all SELECT RESOURCE_TYPE_ID AS id, RESOURCE_TYPE_NAME AS label, PARENT_ID as pid, '0' as type, icon, resource_property,
'0' isEmergency,
0 as isMonitor FROM resource_type where delete_flag = 0 and status='0' and tenant_id = #{tenantId,jdbcType=VARCHAR} and industry_code = #{industryCode,jdbcType=VARCHAR}
AND app_ver_code = #{appVerCode}
AND resource_property = #{resourceProperty}
